// #1b6593 (f38f747408a2e846c51b6593) «iOS - אחרי פרסום שינוי בממשק הניהול, כניסה ל«תפילות» גורמת לקריסת האפליקציה (עד יציאה וכניסה מחדש)»
// — עבר QA 25.10.2026 (iPhone 17, TestFlight 1.0.0 (20) + OTA iOS d4164b5d, commit 1bf6c0b).
// מה רצוי: «מנהל התוכן מפרסם שינוי → המשתמש פותח את האפליקציה ולוחץ על «תפילות» → הרשימה נפתחת בלי קריסה ומציגה את התוכן
// המעודכן, בלי צורך לצאת ולהתחבר מחדש» (опора: S-27 AC4, F-40 AC1, F-102 AC4, F-56 AC4).
// Факт 25.10 (session-2026-10-25.json): קטע «QA-AUTO בדיקת קריסה 25.10» добавлен 11:17 и удалён 11:24 в «ברכת הלבנה · נוסח אשכנז»
// (approver «בודק QA»); 6/6 холодных стартов после публикации/удаления — «תפילות» без падения и без перелогина;
// «רשימת התפילות» из молитвы и из ברכה ✅; у пользователя «1 מתוך 2» после добавления → «1 מתוך 1» после удаления (1b6593-user-seg1.png).
//
// Q-11a (@prod-safe) — без админки: 3 холодных старта → «תפילות», «רשימת התפילות» из молитвы и из ברכה (корень по комменту — рестарт).
// Q-11b (@admin @data, QA_ADMIN_MANUAL=1) — сценарий тикета с публикацией; ВХОД КЛИЕНТА ДЕЛАЕТ ЧЕЛОВЕК. НЕЛЬЗЯ: «אישור כל התפילה»,
// существующие קטעים и קטעים с озвучкой. Возврат: QA קטע удалён и утверждён, счётчики как в начале. Необратимо: 2 строки «היסטוריית אישורים».
// Тест НЕ обходит падение: окно сбоя или экран входа = провал (в отличие от старого обхода в q-09).
// Кейс: .qa/tests/prayer-catalog/PC-06-prayers-no-crash-after-publish.md.
import { expect } from '@wdio/globals';
import { byText, scrollToText } from '../../helpers/ui.ts';
import { skipWith } from '../_lib/app-0710.ts';
import { openAdminPrayer, openSection, setField, saveDraft, approveDraft, qaMarker, historyEntry } from '../_lib/admin.ts';
import { goHome, openProfile, waitHuman, openCatalogPrayer, counterNM, nodes } from '../_lib/readiness-1910.ts';
import { approvedCount, sectionRows, buttonContaining, ADM_ADD_START, ADM_NEW_TITLE } from '../_lib/app-2110.ts';
import { saveShot, coldStart, prayersTabNoCrash, prayersListFromHeader, prayersListFromBracha, deleteOpenSection } from '../_lib/app-2510.ts';

const PRAYER = 'ברכת הלבנה';
const NUSACH = 'אשכנז';
const APPROVER = process.env.QA_APPROVER || 'בודק QA';
const QA_TITLE = `QA-AUTO בדיקת קריסה ${new Date().getDate()}.${new Date().getMonth() + 1}`;
const QA_BODY = 'בדיקת QA — קטע בדיקה זמני, יימחק';
const COLD_RUNS = 3;

async function adminEntryVisible() {
  try { await openProfile(); await scrollToText('ממשק ניהול התוכן', 6); return true; } catch { return false; }
}
/** N холодных стартов, после каждого — «תפילות» без падения. */
async function coldStartsThenPrayers(tag: string) {
  for (let i = 1; i <= COLD_RUNS; i++) {
    await coldStart(`${tag} холодный старт ${i}/${COLD_RUNS}`);
    await prayersTabNoCrash(`${tag} «תפילות» после старта ${i}/${COLD_RUNS}`);
  }
}
/** Экран пользователя «ברכת הלבנה»: [страниц M, текст 1-й страницы]. Без обхода падения. */
async function userPrayer(): Promise<{ total: number; page1: string }> {
  await goHome();
  await openCatalogPrayer(PRAYER);
  const [, total] = await counterNM();
  const page1 = (await nodes()).map((n) => n.label).join('\n');
  return { total, page1 };
}

describe('25.10 — «תפילות» без падения после публикации и холодного старта (#1b6593)', () => {
  after(async () => { await goHome().catch(() => {}); });

  it('Q-11a 3 холодных старта → таб «תפילות» без падения и без перелогина; «רשימת התפילות» из молитвы и из ברכה #1b6593 #f38f7474 S-27 AC4 F-40 AC1 @prod-safe', async function () {
    this.timeout(900000);
    await coldStartsThenPrayers('Q-11a');
    // Из молитвы: «תפילות» → «ברכת הלבנה» → «רשימת התפילות» в шапке.
    await openCatalogPrayer(PRAYER);
    await prayersListFromHeader('молитва → «רשימת התפילות»');
    // Из ברכה.
    await prayersListFromBracha();
    await saveShot('Q-11a-list-from-bracha.png');
  });

  it('Q-11b «אישור ופרסום» QA קטע в «ברכת הלבנה · אשכנז» → 3 холодных старта → «תפילות» и «רשימת התפילות» без падения; у пользователя M+1 страниц и QA קטע на 1-й; удаление + утверждение → 3 старта → M страниц, QA קטע нет; без выхода/входа #1b6593 #f38f7474 F-102 AC4 F-56 AC4 @admin @data @manual-check', async function () {
    this.timeout(3600000);
    if (process.env.QA_ADMIN_MANUAL !== '1') skipWith(this, 'нужен вход клиента (админ) человеком — запуск с QA_ADMIN_MANUAL=1');
    if (!(await adminEntryVisible())) await waitHuman('войдите в приложение аккаунтом КЛИЕНТА (в профиле должен быть «ממשק ניהול התוכן»)', adminEntryVisible);

    // 0. Исходно (25.10: 1 קטע, «0 מתוך 1 קטעים מאושרים»; у пользователя «1 מתוך 1»).
    await openAdminPrayer(PRAYER, NUSACH);
    const [n0, m0] = await approvedCount();
    await scrollToText('קטעי התפילה');
    const orig = await sectionRows();
    if (orig.some((r) => r.includes(QA_TITLE))) throw new Error(`в «${PRAYER}» уже есть «${QA_TITLE}» — убрать вручную перед тестом`);
    const user0 = await userPrayer();
    console.log(`[Q-11b] исходно: админка ${n0}/${m0}, ${orig.join(' | ')}; у пользователя 1 מתוך ${user0.total}`);
    const marks = { add: qaMarker('Q11-add'), del: qaMarker('Q11-del') };
    let added = false;
    try {
      // 1. Добавить QA קטע в начало и утвердить ТОЛЬКО его («אישור ופרסום» у קטע).
      await openAdminPrayer(PRAYER, NUSACH);
      await (await buttonContaining(ADM_ADD_START)).click();
      await (await byText(ADM_NEW_TITLE)).waitForExist({ timeout: 20000 });
      await setField('כותרת הקטע', QA_TITLE);
      await setField('טקסט התפילה', QA_BODY);
      await saveDraft();
      added = true;
      await openAdminPrayer(PRAYER, NUSACH);
      await openSection(QA_TITLE);
      await setField('שם המאשר', APPROVER);
      await approveDraft(marks.add);

      // 2. Холодные старты → «תפילות» ×3 без падения (тикет: было 3/3 падение).
      await coldStartsThenPrayers('Q-11b после публикации');
      // 3. Пользователь видит опубликованное: M+1 страниц, QA קטע на 1-й (добавлен в начало). Затем «רשימת התפילות» из молитвы и ברכה.
      const u1 = await userPrayer();
      expect(u1.total).toBe(user0.total + 1);                // 25.10: «1 מתוך 2»
      expect(u1.page1).toContain(QA_TITLE);
      await prayersListFromHeader('после публикации: молитва → «רשימת התפילות»');
      await prayersListFromBracha();
      await saveShot('Q-11b-after-publish.png');
    } finally {
      // 4. Удалить QA קטע и утвердить удаление (возврат).
      if (added) {
        await openAdminPrayer(PRAYER, NUSACH);
        if ((await sectionRows()).some((r) => r.includes(QA_TITLE))) {
          await openSection(QA_TITLE);
          await deleteOpenSection(QA_TITLE, APPROVER, marks.del);
        }
      }
    }
    // 5. После удаления — снова холодные старты, «תפילות», пользователь видит M страниц без QA קטע (25.10: «1 מתוך 1»).
    await coldStartsThenPrayers('Q-11b после удаления');
    const u2 = await userPrayer();
    expect(u2.total).toBe(user0.total);
    expect(u2.page1).not.toContain(QA_TITLE);
    // 6. Админка как была; история с нашими метками (F-102 AC5).
    await openAdminPrayer(PRAYER, NUSACH);
    const [n1, m1] = await approvedCount();
    expect([n1, m1]).toEqual([n0, m0]);
    await scrollToText('קטעי התפילה');
    expect(await sectionRows()).toEqual(orig);
    for (const mk of Object.values(marks)) await historyEntry(mk);
  });
});
